-- C32 SDN/RSD catalog-group references cross-checked with Cat Parts Store.
-- Reference-only rows: no retail price, stock, or universal serial applicability is inferred.
insert into public.part_catalog
 (part_number,name,description,engine_models,technical_group,source_name,source_url,source_note,verification_status,application_type,application_evidence,application_source_url)
values
('355-0325','مجموعه پمپ کمکی آب دریا Cat 355-0325','Auxiliary sea-water pump group listed in the C32 SDN and RSD Cooling System catalog trees. Cat Parts Store lists Marine Engine C32 as the compatible model; no land application is listed on the retrieved product page.','{C32}','موتورهای دریایی - خنک‌کاری و آب دریا - پمپ آب دریا','Cat Parts Store + K-Part CAT public catalog','https://parts.cat.com/en/catcorp/product/355-0325','K-Part C32/SDN and C32/RSD Cooling System trees list 355-0325 as PUMP GP-AUXILIARY SEA WATER. Cat Parts Store compatible-model listing shows MARINE ENGINE C32 only. Final fitment still requires full engine serial and arrangement confirmation.','REFERENCE','MARINE','Cat Parts Store lists Marine Engine C32; K-Part C32 marine propulsion SDN and marine auxiliary RSD catalogs both list this group under Auxiliary Sea Water.','https://parts.cat.com/en/catcorp/product/355-0325'),
('353-9049','مجموعه مبدل حرارتی آب دریا Cat 353-9049','Sea-water heat exchanger group listed in the C32 SDN Cooling System catalog tree. Cat Parts Store lists both Marine Engine C32 and Generator Set C32.','{C32}','موتورهای دریایی - خنک‌کاری و آب دریا - مبدل حرارتی','Cat Parts Store + K-Part CAT public catalog','https://parts.cat.com/en/catcorp/product/353-9049','K-Part C32/SDN Cooling System tree lists 353-9049 as HEAT EXCHANGER GP-SEA WATER. Cat Parts Store compatible models include Marine Engine C32 and Generator Set C32.','REFERENCE','BOTH','Cat Parts Store explicitly lists Marine Engine C32 and Generator Set C32 as compatible models.','https://parts.cat.com/en/catcorp/product/353-9049'),
('116-1980','پمپ روغن موتور Cat 116-1980','Engine oil pump group listed in the C32 SDN and RSD Lubrication System catalog trees. Cat Parts Store marks the part discontinued and displays Cat Reman 0R-8210 as an alternative; confirm the correct replacement for the exact arrangement before ordering.','{C32}','موتورهای دریایی - روغن‌کاری - پمپ روغن','Cat Parts Store + K-Part CAT public catalog','https://parts.cat.com/en/catcorp/product/116-1980','K-Part C32/SDN and C32/RSD Lubrication System trees list 116-1980 as PUMP GP-ENGINE OIL. Cat Parts Store lists Marine Engine C32 and Marine Auxiliary C32 as compatible, along with land/industrial categories; it also marks 116-1980 discontinued.','REFERENCE','BOTH','Cat Parts Store explicitly lists Marine Engine C32 and Marine Auxiliary C32 as well as non-marine compatible equipment. The product page identifies 0R-8210 as a Cat Reman alternative, not a universal supersession.','https://parts.cat.com/en/catcorp/product/116-1980'),
('207-2422','فیلتر جداکننده آب و سوخت Cat 207-2422','Fuel-water separator filter group listed in the C32 SDN and RSD Fuel System catalog trees. Cat Parts Store lists C32 marine and non-marine compatible equipment.','{C32,C32B,C18,3412E,3406C}','موتورهای دریایی - سوخت - فیلتر جداکننده آب و سوخت','Cat Parts Store + K-Part CAT public catalog','https://parts.cat.com/en/catcorp/product/207-2422','K-Part C32/SDN and C32/RSD Fuel System trees list 207-2422 as FILTER GP-WATER SEP & FUEL. Cat Parts Store compatible models include Marine Engine C32/C32B/C18 and Marine Auxiliary C32, plus Generator Set and land equipment.','REFERENCE','BOTH','Cat Parts Store explicitly lists Marine Engine and Marine Auxiliary models together with Generator Set and non-marine equipment.','https://parts.cat.com/en/catcorp/product/207-2422')
on conflict (part_number) do update set
 name=excluded.name,description=excluded.description,engine_models=excluded.engine_models,
 technical_group=excluded.technical_group,source_name=excluded.source_name,
 source_url=excluded.source_url,source_note=excluded.source_note,
 verification_status='REFERENCE',application_type=excluded.application_type,
 application_evidence=excluded.application_evidence,
 application_source_url=excluded.application_source_url,updated_at=now();
